// The solver chart's generated files (docs/preflop-solver.md §6.2): one index of every shipped stage's metadata and
// one file per stage, written by scripts/make-preflop.mjs. Kept apart from the generator so that tools can write or
// read the same layout without running a solve.
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { gzipSync } from "node:zlib";

/** Relative to the output directory (src/data/sets by default). */
export const INDEX_FILE = "preflopIndex.ts";
export const STAGE_DIR = "preflopStages";
/** The single data file of the releases before the split; a write removes it. */
export const LEGACY_FILE = "preflopData.ts";
/** PF-SIZE-1: gzip (Node's default level) of each stage file, and of every file together, bytes. */
export const STAGE_GZIP_LIMIT = 30_000;
export const TOTAL_GZIP_LIMIT = 200_000;

const HEADER = `// Generated by scripts/make-preflop.mjs. Do not edit by hand; rerun the script instead.
// Solver preflop charts: 9-handed, BB ante 1bb, equal stacks, chip EV. Every number comes from our own DCFR preflop
// solver (src/poker/preflop) with the postflop realization model fitted to our own solver packs
// (src/poker/preflop/eqrFit.ts); a push/fold stage uses showdown equity only. No commercial or third-party chart or
// solver output is used.
// Shape: src/data/sets/preflopTypes.ts. Design and validation: docs/preflop-solver.md.`;

export const stageFile = (id) => `${STAGE_DIR}/${id}.ts`;

/** A stage without its scenarios, every other key in its place. */
export function stageMeta(stage) {
  const { scenarios: _drop, ...meta } = stage;
  return meta;
}

export function indexText(stages, draftIds) {
  // Literal dynamic imports, one per stage file: Vite makes each a chunk, and since this file changes whenever the set
  // of stages does, no transform cache can hold a stale list (an import.meta.glob in a file that does not change can).
  const loaders = stages.map((st) => `  ${JSON.stringify(st.id)}: () => import(${JSON.stringify(`./${STAGE_DIR}/${st.id}`)}),`).join("\n");
  return `${HEADER}
import type { PreflopStage, PreflopStageMeta } from "./preflopTypes";

/**
 * Stages written by a development run (--no-sensitivity, --no-twostart, --ignore-gates or --iterations): their
 * confidence comes only from the checks that ran and their \`move\` is 0. Empty in a release run.
 */
export const PREFLOP_DRAFT_STAGES: string[] = ${JSON.stringify(draftIds)};

/** Every shipped stage in chart order, without its scenarios (the stage files hold the whole stage). */
export const PREFLOP_STAGE_META: PreflopStageMeta[] = ${JSON.stringify(stages.map(stageMeta), null, 1)};

/** Each shipped stage's file (its default export is the whole stage), loaded on first use as its own chunk. */
export const PREFLOP_STAGE_FILES: Record<string, () => Promise<{ default: PreflopStage }>> = {
${loaders}
};
`;
}

export function stageText(stage) {
  return `${HEADER}
import type { PreflopStage } from "../preflopTypes";

const stage: PreflopStage = ${JSON.stringify(stage, null, 1)};
export default stage;
`;
}

/** Every generated file of these stages: relative path → text, the index first, then the stages in order. */
export function preflopFiles(stages, draftIds) {
  const files = new Map([[INDEX_FILE, indexText(stages, draftIds)]]);
  for (const st of stages) files.set(stageFile(st.id), stageText(st));
  return files;
}

export const gzipBytes = (text) => gzipSync(text).length;

/** Per file gzip bytes and the total. */
export function fileSizes(files) {
  const per = new Map();
  let total = 0, raw = 0;
  for (const [path, text] of files) {
    const gz = gzipBytes(text);
    per.set(path, gz);
    total += gz;
    raw += Buffer.byteLength(text);
  }
  return { per, total, raw };
}

/** What PF-SIZE-1 finds wrong with these files; [] when they fit. */
export function sizeProblems(files) {
  const { per, total } = fileSizes(files);
  const out = [];
  for (const [path, gz] of per) if (path !== INDEX_FILE && gz > STAGE_GZIP_LIMIT) out.push(`${path} gzip ${gz} > ${STAGE_GZIP_LIMIT}`);
  if (total > TOTAL_GZIP_LIMIT) out.push(`all files gzip ${total} > ${TOTAL_GZIP_LIMIT}`);
  return out;
}

/** The stage files on disk under dir (relative paths), sorted. */
function stageFilesOn(dir) {
  const d = `${dir}/${STAGE_DIR}`;
  if (!existsSync(d)) return [];
  return readdirSync(d)
    .filter((f) => f.endsWith(".ts"))
    .map((f) => `${STAGE_DIR}/${f}`)
    .sort();
}

/**
 * The files under dir against `files`: those that would change or be added, and those a write would remove (stage files
 * no longer produced and the legacy single file). Empty lists when dir is up to date.
 */
export function compareFiles(dir, files) {
  const changed = [], removed = [];
  for (const [path, text] of files) {
    const full = `${dir}/${path}`;
    if (!existsSync(full) || readFileSync(full, "utf8") !== text) changed.push(path);
  }
  for (const path of stageFilesOn(dir)) if (!files.has(path)) removed.push(path);
  if (existsSync(`${dir}/${LEGACY_FILE}`)) removed.push(LEGACY_FILE);
  return { changed, removed };
}

/** Writes `files` under dir and removes what compareFiles would remove. Returns the removed paths. */
export function writeFiles(dir, files) {
  const { removed } = compareFiles(dir, files);
  mkdirSync(`${dir}/${STAGE_DIR}`, { recursive: true });
  for (const [path, text] of files) writeFileSync(`${dir}/${path}`, text);
  for (const path of removed) rmSync(`${dir}/${path}`);
  return removed;
}
